code:
def squares(n):
    out = []
    for i in range(n):
        out.append(i * i)
    return out

print(squares(6))

def average(nums):
    return sum(nums) / len(nums)

print(average([1, 2, 3]))
print(average([]))

improved_code:
def average(nums):
    """Average."""
    return sum(nums) / len(nums)
print(average([1, 2, 3]))
print(average([]))

code:
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print([fib(i) for i in range(12)])

improved_code:
