code:
def evens(nums):
    result = []
    for n in nums:
        if n % 2 == 0:
            result.append(n)
    return result

print(evens(range(10)))

def is_adult(age):
    if age >= 18:
        return True
    else:
        return False

print(is_adult(20), is_adult(12))

def count_words(text):
    counts = {}
    for w in text.split():
        if w in counts:
            counts[w] = counts[w] + 1
        else:
            counts[w] = 1
    return counts

print(count_words('a b a c b a'))

improved_code:
