code:
def safe_div(a, b):
    try:
        return a / b
    except:
        return None

print(safe_div(4, 2), safe_div(1, 0))

improved_code:
def safe_div(a, b):
    """Safe div."""
    try:
        return a / b
    except Exception:
        return None
print(safe_div(4, 2), safe_div(1, 0))

